parameters.jsCode:
// De aanbieders waarvan LaVega de voorwaarden ophaalt van hun EIGEN tariefpagina.
//
// ALLEEN bronnen die een gewone HTTP-fetch echt toelaten staan hier. Gemeten op
// 2026-08-16, met en zonder browser-User-Agent:
//   ABN AMRO betaal/creditcard  200  (LUKT ALLEEN met de User-Agent-header die
//                                     op de node ernaast staat; zonder die
//                                     header loopt de verbinding in een timeout)
//   bunq                        200
//   Wise                        200  (gemeten 2026-08-16)
//   Knab                        200  (gemeten 2026-08-16)
//   Rabobank                    403
//   N26 / Trade Republic        404  URL bestaat niet
//   Revolut                     403  "Just a quick security check" (Cloudflare)
//   Trading 212                 403  Cloudflare
//   ING (beide)                 verbinding verbroken, ook via HTTP/1.1 (Akamai)
//   American Express Gold       200  (de oude URL was verhuisd; deze klopt)
//
// Die vier zijn niet met een header te repareren: het is een bot-check, geen
// opmaakprobleem. Een reader-proxy (r.jina.ai) werd zelf ook geblokkeerd.
// Ze worden daarom overgelaten aan de reis-agent in LaVega, die ze met web
// search WEL vindt (gemeten: Revolut 0%, ING creditcard 2%, T212 0%).
//
// Dus: deze workflow doet wat een fetch betrouwbaar kan, de agent doet de rest.
// Zet een aanbieder hier pas bij als een kale fetch zijn pagina teruggeeft.
//
// `provider` MOET exact overeenkomen met wat LaVega toont: bank + "betaalpas"
// of "creditcard" (zie productOf() in packages/core/src/travel.ts).
return [
  { json: { provider: 'ABN AMRO betaalpas',  url: 'https://www.abnamro.nl/nl/prive/betalen/in-het-buitenland/index.html' } },
  { json: { provider: 'ABN AMRO creditcard', url: 'https://www.abnamro.nl/nl/prive/creditcards/tarieven.html' } },
  { json: { provider: 'bunq betaalpas',      url: 'https://www.bunq.com/nl/pricing' } },
  { json: { provider: 'Wise betaalpas',      url: 'https://wise.com/nl/pricing/' } },
  { json: { provider: 'Knab betaalpas',      url: 'https://www.knab.nl/tarieven' } },
  // American Express: de oude URL gaf 404, die pagina was verhuisd. Deze werkt
  // (gemeten 2026-08-16, 200). Let op de naam: LaVega vraagt vandaag om
  // "American Express creditcard", want productOf() kent geen kaartvariant. De
  // eigenaar heeft de GOLD CARD, dus dat is de pagina die hier staat. Krijgt hij
  // er een tweede Amex bij, dan moet LaVega eerst variant-namen leren; nu zou
  // een tweede kaart deze cijfers stil overschrijven.
  { json: { provider: 'American Express creditcard', url: 'https://www.americanexpress.com/nl-nl/creditcard/gold-card/' } },
];

// HTML -> platte tekst. Het model hoeft geen opmaak te zien, en een kale
// pagina scheelt tokens en tijd. Alles boven 18k tekens gaat eraf: tarieven
// staan vrijwel altijd in het eerste deel, en een lange staart aan footer-
// en cookieteksten helpt niet.
const out = [];
for (const item of $input.all()) {
  const provider = item.json.provider;
  const url = item.json.url;
  const raw = typeof item.json.data === 'string' ? item.json.data : '';
  if (!raw) { out.push({ json: { provider, url, text: '', ok: false } }); continue; }
  const text = raw
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 18000);
  out.push({ json: { provider, url, text, ok: text.length > 200 } });
}
return out;

parameters.jsonBody:
={{ JSON.stringify({
  model: 'claude-sonnet-5',
  max_tokens: 1024,
  system: 'Je leest de tarievenpagina van een betaalproduct en haalt er cijfers uit. Antwoord UITSLUITEND met JSON, zonder uitleg eromheen: {"fxFeePct": number|null, "cashbackPct": number|null, "pointsPerEuro": number|null, "transferFreeViaIdeal": 0|1|null, "note": string}. fxFeePct = de koersopslag in procenten bovenop de interbancaire koers bij een betaling in vreemde valuta met DIT product. Laat een veld null als de pagina het niet vermeldt — verzin nooit een getal, een verkeerd tarief stuurt iemand met de verkeerde kaart op reis. Zet uitzonderingen (weekendtoeslag, gratis-limiet per maand, kosten voor contant opnemen) in note, niet in de getallen.',
  messages: [{ role: 'user', content: 'Product: ' + $json.provider + '\nBron: ' + $json.url + '\n\n' + $json.text }]
}) }}

parameters.jsCode:
// Het antwoord van het model naar de vorm die LaVega verwacht.
//
// De productnaam zit NIET in het antwoord van Claude, dus die halen we op uit
// de filter-node ervoor: die stuurt 1-op-1 in dezelfde volgorde door, zodat
// item i hier hoort bij aanbieder i daar. (Bewust de filter-node en niet
// "HTML naar tekst", want de filter gooit mislukte pagina's eruit en dan
// lopen de posities niet meer gelijk.)
const sources = $('Pagina gelukt?').all();
const items = $input.all();
const rows = [];

for (let i = 0; i < items.length; i++) {
  const name = sources[i]?.json?.provider;
  if (!name) continue;
  const text = items[i]?.json?.content?.[0]?.text ?? '';
  const match = typeof text === 'string' ? text.match(/\{[\s\S]*\}/) : null;
  if (!match) continue;
  let parsed;
  try { parsed = JSON.parse(match[0]); } catch (e) { continue; }

  const num = (v) => (typeof v === 'number' && isFinite(v) ? v : undefined);
  const row = {
    provider: name,
    fxFeePct: num(parsed.fxFeePct),
    cashbackPct: num(parsed.cashbackPct),
    pointsPerEuro: num(parsed.pointsPerEuro),
    transferFreeViaIdeal: parsed.transferFreeViaIdeal === 1 ? 1 : parsed.transferFreeViaIdeal === 0 ? 0 : undefined,
    note: typeof parsed.note === 'string' ? parsed.note.slice(0, 900) : undefined,
  };
  // Zonder bruikbaar getal weigert LaVega de rij toch — "onbekend" is een
  // eerlijker uitkomst dan een gok, en dan kun jij hem zelf invullen.
  const usable = ['fxFeePct', 'cashbackPct', 'pointsPerEuro', 'transferFreeViaIdeal'].some((k) => row[k] !== undefined);
  if (usable) rows.push(row);
}

return [{ json: { homeCountry: 'NL', currency: 'USD', terms: rows } }];
